  #renderNotificationPanel(){const {i18n,notifications}=this.context,overlay=this.root.querySelector('[data-overlays]'),items=notifications.snapshot().items;overlay.innerHTML=`<div class="floating-panel notification-panel"><header><strong>${i18n.t('notifications')}</strong>${items.length?`<button data-shell-action="clear-notifications">${i18n.t('clearAll')}</button>`:''}</header><div class="notification-list">${items.length?items.map(item=>this.#notificationCard(item)).join(''):`<div class="empty-state">${icon('bell',28)}<span>${i18n.t('noNotifications')}</span></div>`}</div></div>`}
